import { describe, expect, it } from 'vitest';
import { Add, Heaviside, I, Mul, Pow, Sym, asCoeffMul, exp, expandFunc, fn, integrate, meijerg, meijerintIndefinite, meijerintInversion, mul, oo, pi, pow, rational, rewrite, simplify, symbols, together } from '../../src';
