describe("doctests of sympy.integrals.meijerint", () => {
  it("r[0]", () => {
    const s = new Sym('s');
    expect(sympyStr(mul(rational(1, 4), s, pow(pi, rational(-1, 2))))).toBe('s/(4*sqrt(pi))');
  });
  it("r[1]", () => {
    const [t, s] = symbols('t s');
    expect(sympyStr(meijerg([], [], [rational(-1, 2), rational(0)], [], mul(rational(1, 4), t, pow(s, 2))))).toBe('meijerg(((), ()), ((-1/2, 0), ()), s**2*t/4)');
  });
  it("r[2]", () => {
    const [m, t] = symbols('m t');
    expect(sympyStr(meijerg([], [], [mul(rational(1, 2), m)], [mul(rational(-1, 2), m)], mul(rational(1, 4), t)))).toBe('meijerg(((), ()), ((m/2,), (-m/2,)), t/4)');
  });
  // the arguments do not type-check against the public API
  //   meijerint_definite(exp(-x**2), x, -oo, oo)
  //   => (sqrt(pi), True)
  it.todo("meijerint_definite(exp(-x**2), x, -oo, oo)");
  it("meijerint_indefinite(sin(x), x)", () => {
    const x = new Sym('x');
    expect(sympyStr(meijerintIndefinite(fn('sin', [x]), x))).toBe('-cos(x)');
  });
  it("meijerint_inversion(1/x, x, t)", () => {
    const [x, t] = symbols('x t');
    expect(sympyStr(meijerintInversion(pow(x, -1), x, t))).toBe('Heaviside(t)');
  });
});

